// Copy the browser runtime dependencies into public/ (git-ignored):
//   public/vendor/z3/z3-built.{js,wasm,worker.js}   Z3 compiled to WebAssembly (z3-solver)
//   public/vendor/z3/z3-lowlevel.js                 z3-solver's low-level bindings as one ES module
//   public/coi-serviceworker.js                   enables cross-origin isolation on GitHub Pages
//
// The low-level bindings are CommonJS; they are wrapped in a tiny module
// registry instead of pulling in a bundler.

import { mkdirSync, copyFileSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const z3Dir = join(root, "node_modules", "z3-solver", "build");
if (!existsSync(z3Dir)) {
  console.error("node_modules/z3-solver is missing; run `npm install` first.");
  process.exit(1);
}
const out = join(root, "public", "vendor", "z3");
mkdirSync(out, { recursive: true });

for (const f of ["z3-built.js", "z3-built.wasm", "z3-built.worker.js"]) {
  if (existsSync(join(z3Dir, f))) copyFileSync(join(z3Dir, f), join(out, f));
}

const modules = ["index", "types.__GENERATED__", "wrapper.__GENERATED__"];
const parts = [
  "// Generated by tools/build-vendor.mjs from z3-solver/build/low-level (MIT License, Microsoft Corporation).",
  "const __defs = {};",
  "const __cache = {};",
  "function __require(name) {",
  "  const key = name.replace(/^\\.\\//, '').replace(/\\.js$/, '');",
  "  if (__cache[key]) return __cache[key].exports;",
  "  const module = (__cache[key] = { exports: {} });",
  "  __defs[key].call(module.exports, module, module.exports, __require);",
  "  return module.exports;",
  "}",
];
for (const m of modules) {
  const src = readFileSync(join(z3Dir, "low-level", `${m}.js`), "utf8").replace(/\/\/# sourceMappingURL=.*$/m, "");
  parts.push(`__defs[${JSON.stringify(m)}] = function (module, exports, require) {\n${src}\n};`);
}
parts.push("const __lowLevel = __require('index');", "export const init = __lowLevel.init;", "export default __lowLevel;");
writeFileSync(join(out, "z3-lowlevel.js"), parts.join("\n"));

copyFileSync(join(root, "node_modules", "coi-serviceworker", "coi-serviceworker.js"), join(root, "public", "coi-serviceworker.js"));
const pkg = JSON.parse(readFileSync(join(z3Dir, "..", "package.json"), "utf8"));
console.log(`vendor/z3 ready (z3-solver ${pkg.version}); coi-serviceworker.js copied`);
